26	const PROCESSING_FEE = 5;
27	const FIRST_INSURANCE_SURCHARGE = 0.1;
28	const CURSE_SURCHARGE = 0.5;
29	const HIGH_ENCHANTMENT_SURCHARGE = 0.3;
30	const HIGH_ENCHANTMENT_THRESHOLD = 5;
31	const LOYALTY_DISCOUNT = 0.2;
32	const LOYALTY_THRESHOLD_YEARS = 2;
33	
34	/** Premiums are rounded up (in the MHPCO's favour), ignoring float noise. */
35	const roundUp = (amount: number): number => Math.ceil(Number(amount.toFixed(6)));
36	
37	const BASE_PREMIUMS: Record<string, number> = {
38	  sword: 100,
39	  amulet: 60,
40	  staff: 80,
41	  potion: 40,
42	  rune: 25,
43	  moonstone: 25,
44	};
45	
46	const COMPONENT_TYPES = ["rune", "moonstone"];
47	const BLOCK_SIZE = 3;
48	const BLOCK_BASE_PREMIUM = 60;
49	
50	const isComponent = (type: string): boolean => COMPONENT_TYPES.includes(type);
51	
52	const countByType = (items: Item[]): Map<string, number> => {
53	  const counts = new Map<string, number>();
54	
55	  for (const item of items) {
56	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
57	  }
58	
59	  return counts;
60	};
61	
62	/** Exactly BLOCK_SIZE alike components form a building block. */
63	const formsBuildingBlock = (type: string, count: number): boolean =>
64	  isComponent(type) && count === BLOCK_SIZE;
65	
66	const itemBasePremium = (type: string): number => BASE_PREMIUMS[type];
67	
68	/** Alike items are priced together so a building block can be recognised. */
69	const groupBasePremium = (type: string, count: number): number =>
70	  formsBuildingBlock(type, count)
71	    ? BLOCK_BASE_PREMIUM
72	    : count * itemBasePremium(type);
73	
74	/** The policy base premium is the sum of the base premiums of its items. */
75	const policyBasePremium = (items: Item[]): number =>
76	  [...countByType(items)].reduce(
77	    (total, [type, count]) => total + groupBasePremium(type, count),
78	    0,
79	  );
80	
81	const isCursed = (item: Item): boolean => item.cursed === true;
82	
83	const isHighlyEnchanted = (item: Item): boolean =>
84	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
85	
86	/**
87	 * Item-specific surcharges stack additively, as fractions of the item's base
88	 * premium.
89	 */
90	const itemSurchargeRate = (item: Item): number =>
91	  (isCursed(item) ? CURSE_SURCHARGE : 0) +
92	  (isHighlyEnchanted(item) ? HIGH_ENCHANTMENT_SURCHARGE : 0);
93	
94	/**
95	 * Item-specific modifiers apply to the base premium of the affected item,
96	 * not to the policy total.
97	 */
98	const itemSurcharges = (items: Item[]): number =>
99	  items.reduce(
100	    (total, item) =>
101	      total + itemBasePremium(item.type) * itemSurchargeRate(item),
102	    0,
103	  );
104	
105	/**
106	 * Modifiers are expressed as amounts added to (or subtracted from) the base
107	 * premium they apply to, so several modifiers stack additively rather than
108	 * compounding.
109	 */
110	const isLoyalCustomer = (customer: Customer): boolean =>
111	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;
112	
113	/** Policy-wide modifier rates, as fractions of the policy base premium. */
114	const policyModifierRate = (customer: Customer): number =>
115	  FIRST_INSURANCE_SURCHARGE - (isLoyalCustomer(customer) ? LOYALTY_DISCOUNT : 0);
116	
117	const quotePremium = (step: QuoteStep, customer: Customer): number => {
118	  const basePremium = policyBasePremium(step.items);
119	
120	  return roundUp(
121	    basePremium +
122	      itemSurcharges(step.items) +
123	      basePremium * policyModifierRate(customer) +
124	      PROCESSING_FEE,
125	  );
126	};
127	
128	export const runScenario = (scenario: Scenario): ScenarioResults => ({
129	  results: scenario.steps.map((step) => ({
130	    premium: quotePremium(step, scenario.customer),
131	  })),
132	});
